import{_ as a,o,c as t,a2 as l}from"./chunks/framework.CiKk3sJz.js";const g=JSON.parse('{"title":"漫画 · 第 15 话 SVG：图形即 DOM 的矢量语言","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.15-svg.md","filePath":"comics/html/EP.15-svg.md","lastUpdated":1792579602000}'),r={name:"comics/html/EP.15-svg.md"};function s(d,e,i,c,h,n){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="漫画-·-第-15-话-svg-图形即-dom-的矢量语言" tabindex="-1">漫画 · 第 15 话 SVG：图形即 DOM 的矢量语言 <a class="header-anchor" href="#漫画-·-第-15-话-svg-图形即-dom-的矢量语言" aria-label="Permalink to &quot;漫画 · 第 15 话 SVG：图形即 DOM 的矢量语言&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/04-svg">docs/html/04-svg.md</a> ｜ 原画：<a href="./EP.15-svg.svg">EP.15-svg.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，给站点图标切了 16/32/48 三套 PNG，改主题色还要重出图；hover 高亮更是无从下手，怀念起字体图标的时候。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。演示 viewBox 的逻辑坐标、path 指令族，以及 symbol/use 搭一套可上色、可点击、可动画的图标系统。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>SVG 是 Canvas 的反面：它是 XML 描述的<strong>保留模式</strong>矢量图，每个图形都是真实的 DOM 节点——浏览器替你记住&quot;这里有个圆&quot;，你改属性它自动重绘。配合 viewBox 的逻辑坐标系，一份图形定义可以从 16px 无损放到 1600px；图形能绑事件、用 CSS 上色、<code>currentColor</code> 跟随文字色，图标系统由此诞生。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>位图图标的三重税：多尺寸切图、改色重出图、无法交互。雪碧图维护麻烦，字体图标在对齐、语义和多色上都有包袱。当需求是&quot;缩放无损 + 能 hover 能点击 + 随主题变色&quot;，位图路线已经走到头。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>viewBox=&quot;x y w h&quot;</code> 建立一套<strong>逻辑坐标系</strong>，浏览器把它等比映射到 SVG 元素的实际视口——这就是矢量无损缩放的原理。保留模式意味着图形即 DOM：<code>&lt;circle&gt;</code>、<code>&lt;rect&gt;</code>、<code>&lt;path&gt;</code> 都是节点，改属性触发重绘、可以绑 click、CSS 能直接控制 fill/stroke。代价是图形数量成千上万时 DOM 成本高（那时才轮到 Canvas）。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p><code>path</code> 一支笔画万物：<code>M</code> 起笔、<code>L/H/V</code> 直线、<code>Q/C</code> 二次/三次贝塞尔、<code>A</code> 圆弧（七参数）、<code>Z</code> 闭合，小写字母表示相对坐标。描边生长动画：<code>getTotalLength()</code> 取路径总长 L → <code>stroke-dasharray:L</code> → <code>stroke-dashoffset</code> 从 L 动到 0，线条就像被一笔笔画出。图标系统：<code>defs</code> 里放 <code>&lt;symbol&gt;</code> 定义一次，各处 <code>&lt;use href=&quot;#id&quot;&gt;</code> 引用，配合内联使用（外链 <code>&lt;img&gt;</code> 无法用外部 CSS/JS 控制内部）与 <code>currentColor</code>，改一处色全站生效。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>SVG 保留模式：图形即 DOM、浏览器自动重绘、可绑事件可上 CSS；海量图形场景才换 Canvas。</li><li>viewBox 建逻辑坐标系并等比映射视口，一份定义无损缩放；要外部控制样式必须内联。</li><li>描边生长靠 dasharray=总长 + offset 动画到 0；symbol/use 让一份图标定义全站复用。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：同一个 SVG 图标，用 <code>&lt;img src=&quot;icon.svg&quot;&gt;</code> 引入时外部 CSS 改不了它的颜色，改成内联 <code>&lt;svg&gt;</code> 就可以，为什么？</p><p><strong>答</strong>：<code>&lt;img&gt;</code> 引入的 SVG 处于独立的图片资源上下文，与外部文档的 DOM、CSS 完全隔离（同源策略式的边界），外部选择器进不去，JS 也拿不到内部节点。内联 SVG 的图形节点直接存在于当前文档 DOM 中，外部 CSS 规则、<code>:hover</code>、媒体查询和 JS 都能直接作用于它们——这也是图标方案常把 SVG 内联或用 symbol/use（symbol 定义需在同一文档或可被引用的 sprite 中）的根本原因。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>基本形状与 path：rect/circle/polygon 与 M/L/Q/C/A/Z 指令：<a href="./../../examples/html/04-svg/index-01-shapes-path.html">examples/html/04-svg/index-01-shapes-path.html</a></li><li>viewBox 缩放原理与 stroke 描边行为：<a href="./../../examples/html/04-svg/index-02-viewbox-stroke.html">index-02-viewbox-stroke.html</a></li><li>渐变、滤镜与各种视觉效果：<a href="./../../examples/html/04-svg/index-03-gradient-filter.html">index-03-gradient-filter.html</a></li><li>图标系统与描边生长动画：<a href="./../../examples/html/04-svg/index-04-icon-animation.html">index-04-icon-animation.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 16 话《Web Storage》——刷新不丢、关掉再开还在：localStorage 与 sessionStorage 的取舍与封装。</p>',22)])])}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
